function lastSunday(y,m){var d=new Date(Date.UTC(y,m+1,0));return new Date(Date.UTC(y,m,d.getUTCDate()-d.getUTCDay(),1,0,0));}
var now=new Date();
var y=now.getUTCFullYear();
var dst=(now>=lastSunday(y,2))&&(now<lastSunday(y,9));
var madrid=new Date(now.getTime()+(dst?2:1)*3600000);
var dow=madrid.getUTCDay();
var h=madrid.getUTCHours();
var mi=madrid.getUTCMinutes();
var hm=h+mi/60;
var dias=['domingo','lunes','martes','miércoles','jueves','viernes','sábado'];
var abierto=(dow===0)?false:((dow===6)?(hm>=9&&hm<15):(hm>=9&&hm<21));
var prox='';
if(!abierto){if(dow===0||(dow===6&&hm>=15)){prox='el lunes a las 9';}else if(hm<9){prox='hoy a las 9';}else{prox='mañana a las 9';}}
function p(n){return (n<10?'0':'')+n;}
return {centro_abierto:abierto?'si':'no',hora_madrid:p(h)+':'+p(mi),dia_semana:dias[dow],proxima_apertura:prox};
